def transform(grid):
    # Background is the most common color in these sparse line-pattern grids.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        # Find the rightmost foreground cell and its contiguous run.
        j = len(row) - 1
        while j >= 0 and row[j] == bg:
            j -= 1
        if j < 0 or j == len(row)-1:
            continue
        k = j
        while k >= 0 and row[k] != bg:
            k -= 1
        # A multi-cell segment aimed toward the right edge marks the trailing
        # background cells for recoloring.
        if j-k >= 2:
            for c in range(j+1, len(row)):
                out[r][c] = 1
    return out

