def transform(grid):
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        j = len(row) - 1
        while j >= 0 and row[j] == bg:
            j -= 1
        if j < 0 or j == len(row) - 1:
            continue
        k = j
        while k >= 0 and row[k] != bg:
            k -= 1
        run_len = j-k
        # Continue solid terminal segments. For a short isolated endpoint,
        # complete only a nearby repeating pattern with a short suffix.
        paint = run_len >= 2
        if not paint and len(row)-1-j <= 3 and j >= 2:
            paint = row[j-2] != bg
        if paint:
            for c in range(j+1, len(row)):
                out[r][c] = 1
    return out
